export function uniqueWords(text) {
  const seen = new Set();
  const unique = [];

  for (const word of text.match(/\S+/g) ?? []) {
    const normalized = word.toLowerCase();
    if (!seen.has(normalized)) {
      seen.add(normalized);
      unique.push(normalized);
    }
  }

  return unique;
}

